  ]$words$;
  item record;
  word_id uuid;
  source_id uuid;
  test_ids uuid[];
  exact_ids uuid[];
  matching_count integer;
  reviewed_senses integer;
  unknown_matches integer;
  new_count integer := 0;
  existing_count integer := 0;
  linked_count integer := 0;
  affected integer;
  conflicts jsonb := '[]';
begin
  if apply_import then
    -- Keep lookup and writes atomic without adding a uniqueness constraint on lemmas.
    lock table public.vocabulary_entries, public.vocabulary_translations,
      public.sources, public.vocabulary_sources in share row exclusive mode;
  end if;

  if not exists (select 1 from public.languages where code = 'et')
    or not exists (select 1 from public.languages where code = 'ru') then
    raise exception 'Apply the initial Takku schema before running this import';
  end if;

  select array_agg(w.id order by w.id) into test_ids
  from public.vocabulary_entries w
  join public.vocabulary_translations t on t.vocabulary_id = w.id and t.language_code = 'ru'
  where w.language_code = 'et' and lower(normalize(btrim(w.lemma))) = 'koer'
    and w.is_published and w.legacy_id is null
    and cardinality(t.glosses) = 1 and lower(normalize(btrim(t.glosses[1]))) = 'собака'
    and not exists (select 1 from public.vocabulary_sources l where l.vocabulary_id = w.id);

  if test_koer_id is not null and (
    coalesce(cardinality(test_ids), 0) <> 1 or test_koer_id is distinct from test_ids[1]
  ) then
    -- Allow an idempotent rerun for the same now-unpublished test entry.
    if not exists (
      select 1 from public.vocabulary_entries w
      join public.vocabulary_translations t on t.vocabulary_id = w.id and t.language_code = 'ru'
      where w.id = test_koer_id and w.language_code = 'et'
        and lower(normalize(btrim(w.lemma))) = 'koer' and not w.is_published and w.legacy_id is null
        and cardinality(t.glosses) = 1 and lower(normalize(btrim(t.glosses[1]))) = 'собака'
        and not exists (select 1 from public.vocabulary_sources l where l.vocabulary_id = w.id)
    ) then
      raise exception 'Expected one verified test koer entry. Preview again and check its UUID.';
    end if;
  end if;

  for item in
    select * from jsonb_to_recordset(payload) as x(word_et text, translation_ru text, emoji text, source text, page integer)
  loop
    word_id := null;
    with incoming as (
      select distinct lower(normalize(regexp_replace(btrim(x.translation_ru), '[[:space:]]+', ' ', 'g'))) as gloss
      from jsonb_to_recordset(payload) as x(word_et text, translation_ru text)
      where lower(normalize(btrim(x.word_et))) = lower(normalize(btrim(item.word_et)))
    ), existing as (
      select w.id, w.is_published,
        lower(normalize(regexp_replace(btrim(array_to_string(t.glosses, ', ')), '[[:space:]]+', ' ', 'g'))) as gloss
      from public.vocabulary_entries w
      left join public.vocabulary_translations t on t.vocabulary_id = w.id and t.language_code = 'ru'
      where w.language_code = 'et'
        and lower(normalize(btrim(w.lemma))) = lower(normalize(btrim(item.word_et)))
    )
    select count(*),
      array_agg(id order by id) filter (
        where is_published and gloss = lower(normalize(regexp_replace(btrim(item.translation_ru), '[[:space:]]+', ' ', 'g')))
      ),
      count(*) filter (where not is_published or not exists (select 1 from incoming where incoming.gloss = existing.gloss)),
      (select count(*) from incoming)
    into matching_count, exact_ids, unknown_matches, reviewed_senses
    from existing;

    if cardinality(exact_ids) = 1 then
      word_id := exact_ids[1];
      existing_count := existing_count + 1;
    elsif coalesce(cardinality(exact_ids), 0) > 1
      or (matching_count > 0 and (reviewed_senses = 1 or unknown_matches > 0)) then
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'word', item.word_et, 'translation', item.translation_ru, 'page', item.page,
        'reason', case when cardinality(exact_ids) > 1 then 'multiple_exact_published_entries'
          else 'different_or_missing_translation_or_draft' end
      ));
      continue;
    else
      new_count := new_count + 1;
      if apply_import then
        insert into public.vocabulary_entries (language_code, lemma, hint_emojis, is_published)
        values ('et', item.word_et, array[item.emoji], true) returning id into word_id;
        insert into public.vocabulary_translations (vocabulary_id, language_code, glosses)
        values (word_id, 'ru', array[item.translation_ru]);
      end if;
    end if;

    if apply_import then
      select s.id into source_id from public.sources s
      where s.book_id is null and s.lesson_id is null and s.is_published
        and s.page_label = item.page::text and s.citation = item.source
      order by s.id limit 1;
      if source_id is null then
        insert into public.sources (page_label, citation, is_published)
        values (item.page::text, item.source, true) returning id into source_id;
      end if;
      insert into public.vocabulary_sources (vocabulary_id, source_id)
      values (word_id, source_id) on conflict do nothing;
      get diagnostics affected = row_count;
      linked_count := linked_count + affected;
    end if;
  end loop;

  affected := 0;
  if apply_import and test_koer_id is not null then
    update public.vocabulary_entries set is_published = false
    where id = test_koer_id and is_published;
    get diagnostics affected = row_count;
  end if;

  return jsonb_build_object(
    'applied', apply_import, 'total', jsonb_array_length(payload),
    'new_words', new_count, 'existing_words', existing_count,
    'conflicting_words', jsonb_array_length(conflicts), 'conflicts', conflicts,
    'new_source_links', linked_count,
    'distinct_senses', jsonb_build_object('või', jsonb_build_array('или', 'масло')),
    'test_koer_candidates', coalesce(to_jsonb(test_ids), '[]'::jsonb),
    'test_koer_unpublished', affected = 1
  );
end;
$import$;

-- First run with FALSE. Change to TRUE only after reviewing import_summary.
-- Replace NULL with 'the verified candidate UUID' to unpublish only that test word.
select pg_temp.import_tere_pages_206_209(false, null) as import_summary;
